import type { BlogPost } from './types';
import type { ResearchPost } from './types';

export const november06BlogPosts: readonly BlogPost[] = [{"slug":"build-a-timekeeper-onboarding-checklist-for-billing-support","title":"Build a timekeeper onboarding checklist for billing support","description":"A practical onboarding checklist that takes a new billing support specialist from system access to independent time-entry review without skipping source checks.","category":"Onboarding","readTime":"8 min read","thumbnail":"/thumbnails/november-06/build-a-timekeeper-onboarding-checklist-for-billing-support.webp","internalService":"/services/time-entry-review-support","internalSibling":"/blog/write-a-client-billing-guideline-summary-an-assistant-can-use","source":{"label":"NALS, The Association for Legal Professionals","url":"https://www.nals.org/"},"sections":[{"heading":"Start with access, not tasks","paragraphs":["A new billing support specialist needs working access to the matter system, the time-entry ledger, and the approved review checklist before touching a live queue. Confirm read and write permissions separately, because a trainer who can view a record may not be able to correct a field. Ask the new hire to open one sample matter and narrate what each screen shows. That small exercise exposes access gaps before they become silent errors in a real batch.","Give the specialist a named buddy and a written escalation route for the first two weeks. The buddy should be someone who performs the same review work, not only a manager who approves it. Record who answered each access question and when the answer was tested. An onboarding checklist that stops at account creation leaves the hardest part, which is knowing when to stop and ask."]},{"heading":"Map the source systems before the queue","paragraphs":["List every system the review touches and write down which one is authoritative for each field. Time narratives may live in one ledger while matter numbers and client guidelines live in another. The checklist should say where a specialist confirms the client, the matter, the timekeeper, and the applicable rate. When two systems disagree, the specialist needs a rule for which record wins and who resolves the conflict.","Walk through a single day of queue work using the map rather than a slide deck. Ask the new hire to trace one time entry from capture to prebill and mark each handoff on paper. The resulting sketch is often more useful than the formal process document because it shows where the specialist actually hesitates. Keep the sketch with the checklist and revise it when a system changes."]},{"heading":"Teach one review standard end to end","paragraphs":["Choose one representative client and teach the full standard against that client's guidelines. The specialist should see the original guideline, the summary used for review, one clean entry, and one entry that must be escalated. Comparing the two entries is more instructive than reading a list of rules in isolation. Repeat the comparison until the specialist can explain why each entry received its status.","Write the standard as observable checks rather than general advice. Instead of telling someone to review carefully, specify that the narrative must name the task, the matter, and the work performed. Instead of asking for good judgment, list the triggers that require a supervising attorney. Specific checks give the new hire a way to self-correct before a reviewer sees the work."]},{"heading":"Use a shadow block with real records","paragraphs":["Assign a shadow block in which the specialist prepares records but does not release them. The regular reviewer compares the prepared status with the specialist's note and records every difference. Keep the sample small enough that the reviewer can explain each correction during the same day. A shadow block is not a test to pass once; it is a controlled space to surface misunderstanding while the cost is low.","Rotate the shadow sample across matter types and client guidelines instead of using the easiest queue. Include a record with a missing source, one with an unusual rate, and one with a guideline conflict. The new hire should encounter each pattern before owning a live queue. If the sample contains only clean records, the onboarding plan is measuring attendance rather than readiness."]},{"heading":"Define what a new specialist may not decide","paragraphs":["Write a short stop list that names the decisions a billing support specialist must never make alone. Typical examples include changing a rate, approving a write-down, waiving a fee, or interpreting an ambiguous client guideline. The list should also name the person or role that owns each decision. A clear stop list protects the client relationship and gives the specialist confidence to escalate without apology.","Test the stop list with realistic scenarios during onboarding. Describe a request that sounds routine but changes a fee, then ask the specialist what they would do next. The correct answer should include the action they will take and the person they will notify. Scenario practice reveals whether the boundary is understood as a workflow step rather than a vague warning."]},{"heading":"Build a first-week exception log","paragraphs":["Ask the new specialist to keep a simple log of every question that interrupted the work during week one. Record the record type, the missing information, the person consulted, and the answer that resolved it. The log does not need to be elaborate, but it should be specific enough to turn into a checklist change. Patterns in the log are the fastest way to improve the onboarding material.","Review the log at the end of the week with the buddy and the queue owner. Separate questions caused by missing access from questions caused by unclear instructions. Then assign one fix and one owner for each recurring category. By week two the log should shrink, and if it does not, the onboarding plan needs a targeted correction."]},{"heading":"Review with a scored sample","paragraphs":["Before independent work begins, score a small sample against the same acceptance checklist used for routine quality review. Score completeness, source support, status accuracy, and escalation clarity as separate dimensions. A single pass or fail result hides which part of the standard is still weak. Give the specialist the scored sheet and ask them to identify their own highest-risk gap.","Set a clear threshold for release and a clear path when the threshold is missed. A specialist who misses one dimension should receive focused practice rather than a repeat of the entire orientation. Re-score only the weak dimension with new records, then confirm the fix holds on a mixed sample. The goal is a documented readiness decision, not a ceremonial sign-off."]},{"heading":"Hand over ownership in stages","paragraphs":["Move from shadow work to supervised release and then to independent review in defined stages. At each stage, name the volume, the review rate, and the conditions that would send work back to supervision. A gradual handover gives the reviewer evidence that quality holds as the queue becomes less familiar. It also prevents a new specialist from being judged on a single difficult week.","Close the onboarding with a short retrospective and an updated checklist. Ask what took longer than expected, which instruction was unclear, and which system caused the most rework. Assign owners and dates for the changes that should carry into the next hire. The checklist becomes a living artifact when each onboarding produces at least one concrete improvement."]}],"faq":[{"q":"How long should onboarding last before independent work?","a":"The length should follow demonstrated readiness rather than a fixed calendar. Most teams need at least one shadow block, one supervised release, and one scored sample before independent review. A specialist who has only watched someone else work has not yet shown that they can apply the standard. Set stage gates instead of a single start date."},{"q":"What should the first shadow sample include?","a":"Use a small mix of clean, incomplete, and conflicting records from real queues. Include one record that requires escalation so the specialist practices the stop list. Avoid selecting only the simplest matters, because easy samples hide gaps in judgment. Review the differences with the specialist on the same day."},{"q":"Who owns the final readiness decision?","a":"The queue owner or supervising attorney should own the readiness decision and the evidence behind it. The buddy can recommend release after the scored sample, but the accountable owner confirms the boundary. Record the decision, the date, and any conditions attached to it. That record protects both the new specialist and the reviewer."}],"publishedAt":"2026-11-06"},{"slug":"write-a-client-billing-guideline-summary-an-assistant-can-use","title":"Write a client billing guideline summary an assistant can use","description":"How to turn a long client billing guideline into a short, checkable summary that a billing assistant can apply without guessing at the client's intent.","category":"Billing guidelines","readTime":"8 min read","thumbnail":"/thumbnails/november-06/write-a-client-billing-guideline-summary-an-assistant-can-use.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/triage-an-e-billing-rejection-without-reopening-the-whole-invoice","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Why the original guideline is not an operating instruction","paragraphs":["A client billing guideline is written to govern a relationship, not to tell an assistant which field to check on a Tuesday. It may describe prohibited charges in one section and approval expectations in another, leaving the reader to connect them. The assistant needs a summary that puts the check, the evidence, and the escalation in one place. Copying the guideline into a shared folder is not a summary and does not reduce ambiguity.","Start by identifying the decisions the assistant is allowed to prepare and the decisions that remain with the firm. A guideline that says a charge is not permitted still needs a rule for what happens when the charge appears on a draft invoice. The summary should translate that rule into a status the assistant can assign and a note the reviewer can verify. If the guideline does not answer the question, the summary should say so explicitly."]},{"heading":"Capture the client, matter, and effective date","paragraphs":["Every summary needs a client name, the matters it applies to, and the date the guideline took effect. Add the version or source location so a reviewer can confirm the summary matches the current document. A summary without an effective date becomes dangerous during a rate change or a new outside counsel policy. The date also tells the assistant which older matters may still follow a prior rule.","Where a client uses different guidelines for different matter types, create separate summaries rather than one blended page. Blend the rules and the assistant will apply a litigation restriction to a corporate matter. Name the matter type in the summary header and link it to the matter record field that drives the choice. The reviewer should be able to tell in seconds which version applies."]},{"heading":"Translate rules into checkable fields","paragraphs":["Turn each guideline requirement into a field, a value, and an evidence source. A rule about block billing becomes a check on narrative structure with examples of acceptable and unacceptable entries. A rule about travel time becomes a check on the timekeeper, the rate, and the client approval reference. The assistant should not have to interpret a paragraph to know which field to inspect.","Keep the field names aligned with the systems the assistant actually uses. If the billing system calls the field matter identifier, the summary should use the same term rather than introducing a new label. Consistency reduces translation errors and makes training easier. When a field cannot be checked directly, write down the manual evidence that must be attached."]},{"heading":"Separate prohibited charges from approval requirements","paragraphs":["A prohibited charge should never appear on a prebill without a documented exception. An approval requirement is different because the charge may be valid once the right person agrees. Mixing the two categories causes assistants either to strip legitimate charges or to release invalid ones. Give each category its own status and its own escalation route.","For prohibited charges, write the exact action the assistant takes when one is found. The action might be to remove the line, flag it for the billing manager, or hold the prebill until the client responds. For approval requirements, name the approver and the evidence that must be attached. The distinction should be visible in the summary even to someone reading it for the first time."]},{"heading":"Record the source page and version","paragraphs":["Each rule in the summary should point back to the page or section of the client guideline that supports it. A reviewer who questions a status can then check the original wording without searching the entire document. Page references also help when a client issues a revised guideline with only a few changed paragraphs. The summary becomes auditable when every rule has a traceable origin.","Store the source document in a location the assistant can reach without asking for permission each time. Keep the version label in the file name and in the summary header. When a new version arrives, mark the old summary as superseded rather than deleting it. Reviewers may still need the prior rule for matters billed under an earlier agreement."]},{"heading":"Show worked examples for ambiguous rules","paragraphs":["Some guidelines are clear in principle but difficult at the margin, so include two or three worked examples for each ambiguous rule. Show a clean entry, a borderline entry, and an entry that must be escalated. Explain the decision in one sentence per example so the assistant can compare the reasoning. Examples reduce the chance that two reviewers apply the same rule in opposite ways.","Choose examples from the firm's own redacted records when possible, because generic examples often miss the local billing system's quirks. Remove client identifiers and keep the narrative structure intact. Update the examples when a frequent exception reveals a gap in the rule. A summary with no examples tends to be read once and then abandoned under queue pressure."]},{"heading":"Set an escalation route for conflicts","paragraphs":["Write down what the assistant does when the client guideline conflicts with a partner instruction or a matter record field. Name the person who resolves the conflict and the maximum time the record may wait before escalation. The route should include a place to record the question and the answer. Without a route, assistants either guess or stop working, and both outcomes cost the firm.","Distinguish a true conflict from missing information. A conflict requires a decision from an authorized owner, while missing information may only require a call to the matter team. The summary should show the assistant how to tell the difference and what to write in each case. Clear escalation language protects the assistant from being pulled into a judgment the role does not own."]},{"heading":"Review the summary when guidelines change","paragraphs":["Set a review trigger for every new client guideline, annual refresh, or material rate change. Compare the new source with the existing summary and record each addition, deletion, or clarification. Do not rewrite the whole summary when only one section changed, because unnecessary edits create new opportunities for error. A dated change log beside the summary makes the revision visible to reviewers.","Ask the assistants who use the summary to report rules that still cause hesitation. Their questions are evidence that the translation is incomplete or the example is missing. Fix the summary before the next billing cycle and note the change in the log. A guideline summary earns trust when it improves through use rather than sitting unchanged for a year."]}],"faq":[{"q":"Can the summary replace the client guideline?","a":"No, the summary is an operating aid and the client guideline remains the controlling document. Keep the source linked and versioned so a reviewer can verify any rule. Use the summary to make routine checks faster, not to narrow the client's rights. When the two conflict, stop and escalate to the owner."},{"q":"How long should the summary be?","a":"Keep it short enough that an assistant can scan it during a live review. Most summaries work best as a few pages organized by check rather than by the client's document order. Move detailed examples into an appendix if the main summary becomes unwieldy. Length is less important than whether each rule is checkable."},{"q":"Who should approve the summary before use?","a":"The billing manager or supervising attorney who owns the client relationship should approve it. Ask that person to confirm the prohibited charges, approval thresholds, and escalation owners. Record the approval date with the version. An unapproved summary should not be used to release a prebill."}],"publishedAt":"2026-11-06"},{"slug":"triage-an-e-billing-rejection-without-reopening-the-whole-invoice","title":"Triage an e-billing rejection without reopening the whole invoice","description":"A line-level triage method for e-billing rejections that preserves the original submission, routes each defect to its owner, and prevents repeat resubmissions.","category":"E-billing","readTime":"9 min read","thumbnail":"/thumbnails/november-06/triage-an-e-billing-rejection-without-reopening-the-whole-invoice.webp","internalService":"/services/e-billing-support","internalSibling":"/blog/prepare-a-prebill-packet-for-a-partners-fifteen-minute-review","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Read the rejection code before the invoice","paragraphs":["Open the rejection notice and read the code, the message, and the affected line before returning to the invoice. A rejection often names a specific field or rule, and that detail determines whether the fix is clerical or substantive. Starting with the whole invoice encourages a broad rewrite that introduces new defects. Write the rejection code at the top of the triage note so the next reviewer sees the same starting point.","Separate the portal's technical response from the client's billing objection. A missing invoice number, an invalid timekeeper identifier, or an unsupported file format is a technical defect. A challenge to a charge, a rate, or a narrative is a billing decision that belongs to an authorized owner. The assistant can prepare evidence for both, but only one category can be corrected without approval."]},{"heading":"Classify the rejection by owner","paragraphs":["Assign each rejection to one of four owners: the assistant, the billing manager, the timekeeper, or the client contact. The assistant owns formatting and data-completeness fixes that follow a written rule. The billing manager owns guideline interpretation, rate questions, and client communication. The timekeeper owns narrative corrections that require knowledge of the work performed. The label should reflect the decision the item needs, not the person who noticed it first.","Put the owner's name or role in the triage note before any correction begins. An unassigned rejection tends to bounce between people while the resubmission deadline approaches. If the owner is unavailable, name the backup and the date the item was handed over. Ownership should be visible even when the answer is still unknown. The note should survive a shift change and a planned vacation."]},{"heading":"Fix line-level defects first","paragraphs":["Correct the smallest set of fields that caused the rejection before touching anything else. A wrong matter number should not trigger a rewrite of the narrative, and a missing task code should not reopen the rate. Line-level fixes are easier to verify and less likely to disturb approved content. After each fix, re-read the rejection message to confirm the correction actually addresses it.","Keep a before-and-after note for every changed field, including the old value and the new value. The note lets a reviewer confirm that the change is limited to the defect. It also helps the next rejection investigation if the same field fails again. A clean change record is more useful than a polished invoice with no trace of what was corrected."]},{"heading":"Preserve the original submission record","paragraphs":["Save the original submission file, the rejection notice, and the timestamp before editing anything. The original record is the only proof of what the client received and when. If the portal overwrites the submission, export a copy to the approved matter folder immediately. Never rely on a screenshot alone when the underlying file is available.","Record the portal's rejection identifier and the resubmission deadline in the same note. That information connects the technical event to the billing cycle and prevents a late response. If the client requests a different format for the resubmission, save that instruction with the original record. The history should show why the second submission differs from the first."]},{"heading":"Write a resubmission note a reviewer can follow","paragraphs":["The resubmission note should state the rejection reason, the change made, the evidence attached, and the remaining risk. Keep it to a few lines so a reviewer can read it in under a minute. Avoid saying that the issue was fixed without naming the field and the new value. A precise note lets the reviewer approve the resubmission without reconstructing the whole event.","If the correction required a judgment from an attorney or billing manager, quote the approval in the note. Include the approver's role and the date, but do not paste privileged content into the portal. For a charge that remains disputed, state that the resubmission preserves the firm's position and identifies the owner handling the discussion. The note should never imply a settlement or concession that no one approved."]},{"heading":"Set the appeal window and evidence packet","paragraphs":["Some rejections can be corrected and resubmitted, while others require an appeal with supporting evidence. Identify the client's appeal window and the evidence the portal accepts before drafting anything. Typical evidence includes time-entry detail, matter authorization, or a prior written approval. Missing the window can convert a correctable defect into a write-off. Check the portal help page or the client guideline for the current rule before assuming the window is generous.","Build the evidence packet as a small set of labeled files rather than one large attachment. Name each file for the field or line it supports so the reviewer can match evidence to the objection. Keep a copy of the packet in the matter record after submission. If the appeal is denied, the same packet explains what was argued and what remains unresolved."]},{"heading":"Avoid resubmitting the same defect twice","paragraphs":["Before resubmitting, compare the new file against the original rejection message and the portal's validation rules. A second rejection for the same field usually means the correction addressed a symptom rather than the rule. Check the field format, the allowed values, and the client-specific configuration. If the rule is unclear, ask the portal support contact before sending another version.","Track repeat rejection codes by client, matter, and timekeeper so patterns become visible. A code that appears across many matters may point to a template or integration problem rather than individual mistakes. Share the pattern with the billing manager and the system owner, not only with the assistant who fixed the latest instance. Prevention is cheaper than another round of resubmission."]},{"heading":"Close the rejection with a prevention note","paragraphs":["After the invoice is accepted, write a short prevention note in the matter record or the team log. State the root cause, the fix, and the check that should catch it next time. If the fix changed a template, a matter field, or a client instruction, link to that change. A rejection that is closed without a prevention note is likely to return in the next cycle.","Review the week's rejections together and look for one process change worth making. The change might be a new pre-submission check, a clearer matter opening step, or a refreshed guideline summary. Assign an owner and a review date so the improvement does not depend on memory. Over time the rejection log becomes a record of system learning rather than a list of individual errors."]}],"faq":[{"q":"Should the assistant ever correct a charge without approval?","a":"No, a charge correction that changes the amount or the client's obligation requires the authorized owner. The assistant may prepare the correction and attach the evidence for review. The approval should be recorded before resubmission. Formatting and completeness fixes can follow the written rule without a separate charge decision."},{"q":"What belongs in the triage note?","a":"Include the rejection code, the affected line, the owner, the correction made, and the evidence attached. Add the portal deadline and the resubmission identifier. Keep the note short enough to read during a live review. The goal is a traceable decision, not a narrative of everything that happened."},{"q":"How do we stop repeat rejections?","a":"Group rejections by code and by client, then look for a shared cause in the template, the matter setup, or the guideline summary. Fix the cause rather than coaching each instance. Track whether the same code returns in the next cycle. A weekly review of the pattern is more useful than a monthly count."}],"publishedAt":"2026-11-06"},{"slug":"prepare-a-prebill-packet-for-a-partners-fifteen-minute-review","title":"Prepare a prebill packet for a partner's fifteen-minute review","description":"A packet design that puts the decision, the exceptions, and only the needed evidence in front of a partner who has fifteen minutes to review a prebill.","category":"Prebill workflow","readTime":"8 min read","thumbnail":"/thumbnails/november-06/prepare-a-prebill-packet-for-a-partners-fifteen-minute-review.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/audit-matter-record-fields-before-a-monthly-billing-close","source":{"label":"American Bar Association","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Put the decision on the first page","paragraphs":["A partner opening a prebill packet should see the decision before the detail. State the matter, the billing period, the total, and whether the packet recommends release, hold, or a specific correction. Put the recommendation at the top with the exceptions that drive it. The rest of the packet exists to support that first page, not to make the partner search for the point.","Name the person who prepared the packet and the person who owns the next decision. Include the date and the version so the partner knows which draft is in front of them. If the packet is a revision, say what changed since the prior version. A clear first page respects the partner's time and reduces the chance of approving the wrong draft."]},{"heading":"Order exceptions by money and risk","paragraphs":["Sort the exceptions by dollar impact first, then by client or regulatory risk. A large write-down request and a small missing receipt should not receive the same visual weight. Put the highest-value or highest-risk items at the top of the exception page with a one-line reason. The partner can then spend the available minutes on the items that matter most.","Group routine corrections separately so they do not crowd the decisions. A missing task code that the assistant can fix under a written rule does not need partner attention. State that the routine items were corrected and list them in an appendix for audit. Separating preparation from decision is the point of the packet. A short appendix is enough when the correction rule is written and the list is stable."]},{"heading":"Attach only the evidence a partner will open","paragraphs":["For each exception, attach the smallest evidence set that supports the decision. A rate question may need the engagement letter and the prior invoice, while a narrative question may need the time entry and the client guideline. Do not attach the full matter file in the hope that more is better. Excess evidence slows the review and makes the relevant fact harder to find.","Label each attachment with the exception it supports and the page or field to check. Use a consistent naming pattern so the partner can move from the packet to the evidence without guessing. If an attachment contains privileged or sensitive material, mark it and limit distribution. The packet should make the evidence easy to verify, not merely available."]},{"heading":"Separate missing information from disagreement","paragraphs":["Mark a record as incomplete when a required field or source is absent. Mark it as disputed when the information exists but the correct treatment is contested. The two statuses lead to different next steps and different owners. Combining them into one exception category causes the partner to spend time on a question that a matter team member could answer.","For incomplete records, name the person or system that can supply the missing item and the date it was requested. For disputed records, state the competing positions and the decision the partner is being asked to make. A short distinction on the exception page prevents the review from turning into an investigation. It also gives the assistant a clear follow-up path after the meeting."]},{"heading":"Write the one-line recommendation carefully","paragraphs":["The recommendation should state an action, not a sentiment. Write release the invoice, hold line twelve pending client approval, or reduce the charge to the approved rate. Avoid phrasing such as looks reasonable or seems fine, because it does not tell the partner what approval would do. A specific recommendation is easier to accept, reject, or modify.","Support the recommendation with the rule and the evidence, not with the assistant's confidence. If the rule is ambiguous, say which interpretation was used and who confirmed it. If no one confirmed it, say that the decision is still open. Honest uncertainty is more useful than a confident recommendation built on an unstated assumption. A recommendation that cannot name its rule is not ready for the packet."]},{"heading":"Keep the review packet short enough to finish","paragraphs":["Set a page budget for the packet and treat it as a design constraint. Most partner reviews can work with a one-page summary, a short exception list, and a small evidence appendix. If the packet exceeds the budget, move routine detail to a secondary file rather than shrinking the font. The partner should be able to finish the review in the time available.","Test the packet with the intended reviewer before the busy close period. Ask where they looked first, what they could not find, and which attachment they ignored. Use that feedback to reorder the pages and remove unnecessary material. A packet designed around actual reading behavior is more effective than one organized around the preparer's workflow."]},{"heading":"Record the partner's decision in place","paragraphs":["Capture the decision next to the exception it resolves, not in a separate email thread. Record the approver, the date, the action approved, and any condition attached to it. If the partner approves a range or delegates a follow-up, write the boundary explicitly. The record should let a later reviewer understand what was authorized without asking the partner again.","Send the decision record to the billing team and the matter owner the same day. Update the prebill status only after the record is saved. If the partner asks for a change that affects another matter or client, route it through the appropriate owner rather than applying it broadly. A decision recorded in place is easier to audit and harder to misapply."]},{"heading":"Use the next packet to fix the template","paragraphs":["After the review, note which exceptions recurred and why the template did not prevent them. A repeated missing field may call for a matter-opening check, while a repeated narrative issue may call for a timekeeper prompt. Assign one template or workflow change and a date to test it. The packet improves when each review produces a specific fix.","Compare the time spent preparing the packet with the time the partner spent reviewing it. If preparation is growing while review time stays flat, the packet may be carrying unnecessary detail. If review time is growing, the first page or the exception ordering may be weak. Use both numbers to guide the next redesign rather than guessing."]}],"faq":[{"q":"How many exceptions should a packet include?","a":"Include every exception that requires a decision, but group routine corrections separately. If the decision list is long, order it by value and risk and summarize the remainder. The partner should not have to read every routine item to find the few that need judgment. A long list is acceptable when the priority is clear."},{"q":"What if the partner wants the full file?","a":"Keep the full file available and link to it from the packet rather than attaching it by default. Note the specific documents that support each exception. If the partner asks for more, add the requested evidence for the next review. Respecting the page budget does not mean hiding the record."},{"q":"Who prepares the recommendation?","a":"The billing support specialist can draft the recommendation from the written rule and the evidence. The supervising attorney or billing manager remains accountable for the decision. The packet should show who prepared it and who approved it. A recommendation is not an approval."}],"publishedAt":"2026-11-06"},{"slug":"design-an-invoice-follow-up-log-that-survives-turnover","title":"Design an invoice follow-up log that survives turnover","description":"A follow-up log design that keeps the next action, the client commitment, and the handover note visible when the person who owns the relationship changes.","category":"Invoice follow-up","readTime":"9 min read","thumbnail":"/thumbnails/november-06/design-an-invoice-follow-up-log-that-survives-turnover.webp","internalService":"/services/invoice-follow-up","internalSibling":"/blog/run-a-weekly-billing-exception-stand-up-that-stays-short","source":{"label":"U.S. Small Business Administration","url":"https://www.sba.gov/business-guide/manage-your-business/stay-legally-compliant"},"sections":[{"heading":"Make the next action the primary field","paragraphs":["A follow-up log should answer one question first: what happens next and who will do it. Put the next action, the owner, and the due date at the top of the entry instead of burying them under a long history. A reader who has never touched the account should be able to continue the work without reading every prior note. If the next action is unclear, the entry is not ready to save.","Use action verbs that describe a specific step, such as call the client contact, send the revised invoice, or confirm receipt with the accounts payable team. Avoid vague entries like follow up, which tell the next person nothing about the channel or the purpose. When an action depends on another person, name that dependency and the date it is expected. A specific next action is the core of a handover-ready log."]},{"heading":"Record the promise in the client's words","paragraphs":["When a client makes a commitment, record what they said they would do and when, not your interpretation of it. A client who says the invoice will be reviewed after the monthly close has given a different timeline from one who says it will be paid by Friday. Quote the commitment briefly and note who made it. The distinction matters when the next person has to decide whether to escalate.","Separate the client's promise from the firm's promise. If the firm agreed to send a corrected invoice or hold a charge, record that commitment with the same care. Both sides of the conversation shape the next action, and a one-sided log leads to avoidable disputes. A short commitment field prevents the log from becoming a collection of guesses."]},{"heading":"Separate contact attempts from commitments","paragraphs":["Log every contact attempt with the date, channel, and person reached, but do not treat an attempt as progress. A voicemail or an unanswered email is activity, not a commitment. The next action should reflect what is still needed rather than what was already tried. This distinction keeps the aging clock honest and prevents false closure.","When a client responds without making a commitment, record the response and set the next action explicitly. A reply that says the invoice is under review may require a follow-up date and a named contact. If the response raises a dispute, route it to the billing manager rather than continuing routine reminders. The log should show the state of the conversation, not only the number of touches."]},{"heading":"Keep the aging clock visible","paragraphs":["Show how long the invoice has been open and how long it has been since the last meaningful response. Age alone can mislead when a client is waiting on the firm, so track the last action by each side. A visible clock helps the team prioritize the accounts that need attention this week. It also exposes promises that have quietly expired.","Set thresholds for routine reminders, manager review, and escalation, and write them next to the clock. The thresholds should reflect the client relationship and the firm's policy rather than a single rule for every account. When a threshold is crossed, the log should prompt a specific next step. A clock without a rule is only decoration."]},{"heading":"Link each entry to the invoice and matter","paragraphs":["Use the invoice number and matter number as the stable links between the log and the billing system. A free-text client name is not enough when a client has multiple matters or entities. The link lets a reviewer confirm the balance, the due date, and the prior correspondence without searching. It also prevents a note from being attached to the wrong account.","Record the invoice version and the amount in dispute when the entry concerns a correction or a partial payment. A follow-up about a revised invoice should point to the version the client actually received. If the invoice is reissued, link the new record to the old one rather than starting a separate history. Continuity matters more than a tidy list of unrelated entries."]},{"heading":"Set a handover note for every open item","paragraphs":["Every open item needs a handover note that explains the relationship context, the latest commitment, and the risk if the date slips. Write it as if the next reader has five minutes and no prior knowledge. Include the client's preferred channel and any sensitivity around the balance. A handover note is not a summary of everything; it is the shortest path to competent continuation.","Review open items before a planned absence, not after the person has left. Ask the owner to update the next action and confirm that the backup can access the invoice and the correspondence. If the backup cannot continue without a password or a portal permission, fix that before the handover. Turnover is predictable enough to plan for."]},{"heading":"Review stale entries weekly","paragraphs":["Run a weekly review of entries with no meaningful action in the prior period. Separate items waiting on the client from items waiting on the firm, because the two require different responses. An item waiting on the firm may need an internal owner and a completion date. An item waiting on the client may need a new contact attempt or a manager decision.","Close entries only when there is a named outcome, such as payment received, a credit approved, or a dispute routed to the right owner. Do not close an entry because it is old or because someone promised to handle it. A closed entry without an outcome hides the work that is still unresolved. The weekly review should leave fewer open questions, not fewer visible records."]},{"heading":"Retire entries with a named outcome","paragraphs":["When an entry is resolved, record the outcome, the date, and the person who confirmed it. Link the outcome to the invoice status so the log and the billing system agree. If the resolution changed a charge or a payment plan, note the approval behind it. A clean retirement record is the evidence that the follow-up actually ended.","Keep resolved entries available for a defined retention period so a later dispute can be reconstructed. Do not delete the history when the invoice closes, because the correspondence may still matter. Archive the entry with the same identifiers used during the follow-up. The log survives turnover when its closed records remain readable. Set the retention period with the finance owner rather than leaving it to habit."]}],"faq":[{"q":"What is the most important field in a follow-up log?","a":"The next action, because it tells the next person how to continue the work. Pair it with an owner and a due date so it cannot sit unresolved. The commitment and aging fields support that action but do not replace it. An entry without a next action is a note, not a workflow."},{"q":"How often should the log be reviewed?","a":"Review open items weekly and before any planned absence. A weekly review catches expired promises while there is still time to act. A handover review confirms that a backup can access the record and continue. Daily review is usually unnecessary unless the account is high risk."},{"q":"Can the log live in a spreadsheet?","a":"A spreadsheet can work if access is controlled and the fields are consistent. The important requirement is that the record is findable by invoice and matter, not that it uses a particular tool. Avoid storing sensitive details in a personal file that the team cannot reach. A shared, permissioned location is part of the control."}],"publishedAt":"2026-11-06"},{"slug":"set-write-down-approval-limits-for-delegated-billing-work","title":"Set write-down approval limits for delegated billing work","description":"How to define write-down thresholds, evidence, and escalation routes so a billing assistant can prepare adjustments without owning the approval decision.","category":"Write-downs","readTime":"9 min read","thumbnail":"/thumbnails/november-06/set-write-down-approval-limits-for-delegated-billing-work.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/audit-matter-record-fields-before-a-monthly-billing-close","source":{"label":"American Bar Association","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Start from the firm's actual authority policy","paragraphs":["Write-down authority should come from the firm's existing policy, not from a new rule invented for the assistant. Identify who may approve a reduction, at what amount, and under which client agreements. The assistant's role is to prepare the request and the evidence, not to expand the set of people who can approve it. If the policy is unwritten, the first task is to document the current practice with the responsible partner.","Check whether client outside counsel guidelines impose their own approval or notice requirements. A write-down that is routine under the firm's policy may still require client consent or a specific disclosure. Record those conditions in the same place as the internal threshold. The combined rule should tell the assistant when a request can move forward and when it must stop."]},{"heading":"Distinguish preparation from approval","paragraphs":["Preparation includes gathering the time entries, the billing history, the client agreement, and the reason for the adjustment. Approval is the decision that the firm will reduce or waive a charge. The assistant can complete the first part and must route the second to an authorized owner. Keeping the two steps separate protects the client relationship and the firm's revenue.","Describe the assistant's output as a decision packet rather than a decision. The packet should state the proposed adjustment, the basis, the affected invoices, and the approver who is needed. It should also note any alternative the approver might prefer, such as a credit or a payment plan. A well-built packet makes the approval faster without pretending the decision is clerical."]},{"heading":"Set thresholds by role and matter risk","paragraphs":["A single dollar threshold for every matter is easy to write but often wrong. A small adjustment on a sensitive client may need partner review, while a larger routine correction may sit with a billing manager. Set thresholds by role, matter type, and client risk so the approval level matches the consequence. Write the matrix in plain language and test it against recent examples.","Include a cumulative threshold as well as a per-invoice limit. Several small adjustments across a billing cycle can add up to a material reduction that no single approval captured. The assistant should be able to see the cumulative amount for the matter and route the request when it crosses the limit. A cumulative rule prevents the appearance of splitting a decision into smaller pieces."]},{"heading":"Require a reason code and evidence","paragraphs":["Every write-down request should carry a reason code, a short narrative, and the evidence that supports it. Common reason codes include a billing guideline conflict, a timekeeping error, a client accommodation, and a collection compromise. The code makes patterns visible, while the narrative explains the specific facts. The evidence should be the smallest set that lets the approver verify the reason.","Do not accept a reason code without the corresponding record. A guideline conflict needs the guideline section, and a timekeeping error needs the entry and the correction. A client accommodation needs the communication or approval that established it. The assistant should return an incomplete request rather than filling the gap with an assumption. The return note should ask for the specific missing item, not for better documentation in general."]},{"heading":"Route exceptions before the prebill closes","paragraphs":["Write-down requests should reach the approver before the prebill is released, not after the invoice has been sent. A late request can force a credit, a revised invoice, or an awkward client conversation. Build the routing step into the prebill checklist so the assistant cannot close the packet while an approval is pending. The approver needs enough time to read the evidence and decide.","If a client deadline makes the normal route impossible, define an expedited path with a named backup approver. Record why the expedited path was used and who authorized it. Do not let urgency become a reason to skip the evidence or the approval. The exception should be visible in the record so the firm can review whether the process needs to change."]},{"heading":"Log every approval with the approver","paragraphs":["Record the approver's name or role, the date, the amount approved, and any conditions attached to the decision. If the approver changed the requested amount, record the final amount separately from the proposal. The log should let a later reviewer reconstruct who decided what and on which evidence. A decision without an approver is not an approval.","Keep the log in a system that the billing team and the finance owner can access. A personal inbox is not an approval log because it disappears when the person leaves. Link each entry to the matter and the invoice so the record can be found from either direction. The log becomes the evidence trail for the next audit or client question."]},{"heading":"Sample approvals for consistency","paragraphs":["Review a small sample of approvals each month and compare the reason, the evidence, and the amount across similar cases. Look for the same reason receiving different treatment or a threshold being applied inconsistently. A sample of five to ten decisions is often enough to reveal a pattern. Share the findings with the approvers without turning the review into a blame exercise.","When the sample shows disagreement, clarify the rule or the evidence standard rather than retraining everyone on general principles. If two approvers read the same guideline differently, the guideline summary needs a worked example. If one approver consistently asks for more evidence, the packet template may be missing a field. Fix the system that produced the variation."]},{"heading":"Revisit limits after a pattern appears","paragraphs":["Review the thresholds when the volume, the client mix, or the firm's policy changes. A limit that fit a small practice may be too high when the billing team grows or when a client adds a new guideline. Use the approval log to see where requests cluster and where approvals take too long. Adjust the matrix with the responsible partner rather than by convenience.","Document the reason for each change and the date it takes effect. Tell the assistants which requests move to a new approver and which evidence requirements changed. A threshold update that is not communicated will be applied unevenly. The policy stays usable when the change history is as visible as the current matrix. Keep the old matrix available so a reviewer can see what applied to an earlier invoice."]}],"faq":[{"q":"Can an assistant approve a small write-down?","a":"Only if the firm's written policy explicitly delegates that authority to the role. Preparation and approval are different acts, and a small amount does not automatically make a decision clerical. The approval should be recorded with the approver and the evidence. When the policy is silent, the assistant should route the request."},{"q":"What evidence should accompany a request?","a":"Include the affected time entries or invoice lines, the client guideline or agreement, and the reason for the adjustment. Add any prior approval or communication that supports the request. Keep the packet small enough for the approver to review. Missing evidence should return the request to the preparer."},{"q":"How do we prevent split approvals?","a":"Track a cumulative amount by matter and billing cycle, not only a per-invoice amount. Route the request when the cumulative total crosses the threshold. Review the log for clusters of small adjustments that share a reason. A cumulative rule makes the pattern visible before it becomes material."}],"publishedAt":"2026-11-06"},{"slug":"audit-matter-record-fields-before-a-monthly-billing-close","title":"Audit matter record fields before a monthly billing close","description":"A pre-close field audit that catches missing matter data, stale rates, and billing contact gaps before they turn into rejected invoices or delayed payments.","category":"Matter records","readTime":"8 min read","thumbnail":"/thumbnails/november-06/audit-matter-record-fields-before-a-monthly-billing-close.webp","internalService":"/services/matter-record-upkeep","internalSibling":"/blog/prepare-a-prebill-packet-for-a-partners-fifteen-minute-review","source":{"label":"Internal Revenue Service","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},"sections":[{"heading":"Choose the fields billing cannot close without","paragraphs":["Start with the fields that block a prebill or an e-billing submission when they are missing. Typical examples include the client entity, the matter number, the billing contact, the rate schedule, and the timekeeper assignment. Add any client-specific field that the portal validates, such as a purchase order or a matter identifier. The audit should focus on fields with a known downstream consequence.","Separate mandatory fields from useful fields so the audit does not become an endless cleanup. A missing marketing code may matter to the firm, but it should not hold a billing close. A missing billing contact or rate can stop an invoice. Rank the fields by their effect on the current cycle and review the rest on a slower cadence."]},{"heading":"Run the check before the prebill cycle","paragraphs":["Schedule the field audit before the prebill cycle begins, not during the final review. Early detection gives the matter team time to correct a record without delaying the invoice. A short audit window also makes it easier to compare the same fields across matters. Waiting until the draft invoice exists turns a data fix into a billing emergency.","Publish the audit date and the fields being checked so matter teams know what to expect. Send a reminder to the owners of matters with open exceptions. If a correction requires a partner decision, name the deadline before the prebill locks. A predictable schedule reduces the number of last-minute requests. A short reminder with the field list and the deadline is usually enough."]},{"heading":"Compare the matter record to the engagement letter","paragraphs":["Check the client entity, the matter description, the fee arrangement, and the billing contact against the engagement letter. A record that has drifted from the agreement can produce an invoice the client did not authorize. Pay particular attention to entities with multiple subsidiaries or matters with a shared billing contact. The engagement letter is the source of truth for the commercial terms.","When the record and the letter differ, do not correct the record from memory or from a prior invoice. Route the discrepancy to the owner who can confirm the current terms. Record the question and the answer with the date. A field audit is only useful if it resolves ambiguity rather than replacing one assumption with another."]},{"heading":"Flag missing client billing contacts","paragraphs":["A missing or outdated billing contact is one of the most common reasons an invoice stalls after it leaves the firm. Confirm the contact name, email, phone, and any portal requirement before the close. If the client uses a shared accounts payable address, record it alongside the relationship contact. The invoice should have a clear destination and a person who can answer a question.","Check whether the contact has changed since the last invoice and whether the client requires a copy to another address. A new contact may need to be introduced before a large invoice arrives. For clients with strict submission rules, confirm that the contact is authorized to receive the invoice. A correct contact field prevents a collections problem that looks like a billing problem."]},{"heading":"Check rate and timekeeper assignments","paragraphs":["Confirm that each timekeeper assigned to the matter has a rate that matches the current agreement or rate notice. Look for timekeepers who transferred from another matter, because their prior rate may follow them by mistake. Check the effective date of any rate change and whether the client approved it. A rate error can invalidate an otherwise clean invoice.","Review the matter's timekeeper list for people who should no longer bill to it. A departed timekeeper or a reassigned associate can create entries that are difficult to support later. Confirm that new timekeepers have the required client approval before they record time. The audit should catch the assignment before the prebill, not after the client questions it."]},{"heading":"Catch duplicate or retired matter numbers","paragraphs":["Search for duplicate matter numbers, reopened matters, and records that were retired but still receive time. A duplicate can split the billing history and make a balance look wrong even when the underlying work is correct. A retired matter that still accepts time can produce an invoice the client did not expect. Resolve the record before the entries are rolled into the prebill.","When two records appear to describe the same matter, compare the engagement letter, the client entity, and the billing history before merging anything. A merge can destroy the audit trail if the records represent different engagements. Route the decision to the matter owner and document the resolution. The goal is a clean billing record, not a tidy list at any cost."]},{"heading":"Give the owner a short correction list","paragraphs":["Send each matter owner a short list of the fields that need attention and the reason each one matters. Avoid a full export of every field, because the owner will not know where to start. Group corrections by owner and deadline so the work can be completed in one pass. A focused list is more likely to be acted on than a general data-quality reminder.","Include the source the owner should use to confirm the correction, such as the engagement letter or the client portal. Ask for the corrected value rather than a note that it will be handled later. If the owner cannot resolve the item before the deadline, record the escalation path. The audit closes when the blocking fields are resolved or formally deferred."]},{"heading":"Record what changed and why","paragraphs":["Keep a change log for the fields corrected during the audit, including the old value, the new value, and the person who confirmed it. The log supports the next audit and helps explain a billing difference if a client asks. It also shows whether the same fields fail every month. A repeated failure points to a matter-opening or integration problem rather than individual carelessness.","At the end of the close, review the log for one systemic fix worth making. The fix might be a required field at matter opening, a validation rule in the billing system, or a clearer handoff from the engagement team. Assign an owner and a review date. The field audit becomes valuable when it reduces next month's correction list."]}],"faq":[{"q":"How many matters should the audit cover?","a":"Cover every matter that will be billed in the cycle, using a field-level check rather than a full manual review. If the population is large, prioritize matters with new clients, rate changes, or prior rejections. The audit should be repeatable and scoped to fields that affect billing. A sample can supplement the check but should not replace it for blocking fields."},{"q":"Who fixes a missing field?","a":"The matter owner or the team that maintains the client record should fix it, depending on the field. The billing assistant can flag the gap and prepare the correction, but should not invent a client entity or rate. Record the owner and the deadline. The audit is a detection and routing process, not an authorization to change terms."},{"q":"What if the correction cannot be made before close?","a":"Document the deferral, the reason, and the person who accepted the risk. Hold the affected invoice if the missing field would prevent a valid submission. Do not release a prebill with a known blocking defect merely to meet the calendar. The deferral record should be reviewed at the next close."}],"publishedAt":"2026-11-06"},{"slug":"run-a-weekly-billing-exception-stand-up-that-stays-short","title":"Run a weekly billing exception stand-up that stays short","description":"A tight weekly meeting format for billing exceptions that assigns owners, clears aged items, and keeps policy debates out of the operating queue.","category":"Billing operations","readTime":"8 min read","thumbnail":"/thumbnails/november-06/run-a-weekly-billing-exception-stand-up-that-stays-short.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/design-an-invoice-follow-up-log-that-survives-turnover","source":{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},"sections":[{"heading":"Bring only exceptions with owners","paragraphs":["A weekly stand-up should start with a list of exceptions that already have an owner and a next action. The meeting is for decisions and unblocking, not for discovering the queue from scratch. Ask each owner to update the status before the meeting so the time is spent on what changed. An exception without an owner should be assigned before it reaches the agenda.","Keep routine completed work out of the discussion unless it reveals a pattern. Reading a list of closed items consumes the meeting without improving the queue. If a closure changed a rule or exposed a defect, note it in one sentence and move on. The agenda should focus on items that still need a decision or a handoff."]},{"heading":"Set a fixed agenda and time box","paragraphs":["Use the same agenda every week: aged items, high-value items, new exceptions, and one prevention topic. Give each section a time box and stop when the box expires. A predictable structure helps participants prepare and keeps the meeting from expanding into a general operations review. The time box is a signal that the meeting has a defined job.","Start on time even if some participants are late, and end with the decisions recorded. Do not extend the meeting to cover every item; move unfinished items to the next agenda or to a separate discussion. A meeting that regularly overruns is usually trying to solve problems that need a different forum. Protect the time box as a rule rather than a suggestion."]},{"heading":"Start with aged and high-value items","paragraphs":["Review the oldest exceptions and the ones with the largest financial or client impact first. These are the items most likely to become a write-off, a missed deadline, or a relationship problem. A simple age and value sort is enough to set the order. Starting with the newest or easiest items leaves the real risk until the end, when attention is lowest.","For each aged item, ask what changed since the last review and who owns the next step. If nothing changed, the item may need a different escalation rather than another week on the list. Record the reason for the delay so the pattern can be addressed later. An aged list that never changes is a sign that the meeting is not resolving the underlying block."]},{"heading":"Ask for the next action, not a status speech","paragraphs":["Replace a general status update with a specific question: what is the next action, who owns it, and when will it happen. This keeps the discussion concrete and gives the recorder something useful to capture. A participant who does not know the next action should say so and ask for help. The meeting should produce commitments rather than descriptions of activity.","If an item has been discussed for two weeks without a next action, treat that as a decision problem. The owner may need authority, information, or a different route. Assign the decision to a named person and set a date for the answer. Repeating the same discussion without a decision is the fastest way to make the meeting feel pointless."]},{"heading":"Park policy debates outside the meeting","paragraphs":["A weekly exception stand-up is not the right place to settle a new billing policy or interpret a complex client guideline. Those questions need the responsible owner, the source document, and enough time to consider the consequences. Park the issue, name the decision owner, and set a separate date. The stand-up can record the dependency without trying to resolve it in five minutes.","Distinguish a policy question from an exception that needs a decision under an existing rule. If the rule already exists, the owner can decide in the meeting and the recorder can capture it. If the rule is missing or contested, the item moves to the policy forum. This distinction keeps the meeting short and protects the quality of the policy decision."]},{"heading":"Assign one owner per exception","paragraphs":["Every exception should have one accountable owner, even when several people contribute. Shared ownership sounds collaborative but often means no one is responsible for the next step. Name the owner in the record and make clear what they are expected to decide or deliver. Contributors can be listed separately without diluting accountability. The owner does not have to do every step, but they must know when the item is done.","When ownership changes, record the handover and the date rather than quietly reassigning the item. The new owner should confirm that they have the context and the access needed to continue. If the handover is temporary, name the date the original owner returns. Clear ownership makes the weekly review faster and the follow-up more reliable."]},{"heading":"Publish decisions the same day","paragraphs":["Send a short decision log after the meeting with the item, the decision, the owner, and the due date. Do not wait for a polished report or the next meeting to confirm what was agreed. A same-day log prevents participants from leaving with different memories of the outcome. It also gives absent stakeholders a way to catch up without asking for a recap.","Keep the log in the same place as the exception queue so the decision and the work stay connected. Update the queue status after the log is published, not before. If a decision changes a rule or a template, link to the change record. A decision that cannot be found later is only slightly better than one that was never made."]},{"heading":"Measure whether the meeting shrinks","paragraphs":["Track the number of open exceptions, the median age, and the share that leave the meeting with a new action. A healthy stand-up should reduce the backlog or keep it stable while resolving the oldest items. If the list grows every week, the meeting may be documenting work rather than unblocking it. Use the numbers to adjust the agenda, not to judge individual participants.","Review the meeting format after a month and ask participants what could be removed. A section that never produces a decision may belong in a written update. A recurring policy debate may need a standing forum. The goal is a short meeting that protects the queue and the client relationship, not a ritual that consumes the team's attention."]}],"faq":[{"q":"How long should the stand-up last?","a":"Thirty minutes is enough for most teams when the agenda and owners are prepared in advance. The exact length matters less than the time box and the focus on decisions. If the list regularly needs more time, move detailed problem-solving to a separate session. A shorter meeting with clear actions is better than a longer one without them."},{"q":"Who should attend?","a":"Include the people who own exceptions and the person who can authorize the decisions that commonly arise. A billing manager, a supervising attorney, and the support lead often cover the necessary authority. Invite others only when their item is on the agenda. Attendance should follow the work, not the org chart."},{"q":"What if an owner misses the meeting?","a":"Require a written update before the meeting and assign a backup for time-sensitive items. Do not let an absent owner stall an aged or high-value exception. The recorder should note the missing update and the escalation route. Repeated absences are an ownership problem, not a scheduling problem."}],"publishedAt":"2026-11-06"}];

export const november06ResearchPosts: readonly ResearchPost[] = [{"slug":"how-often-do-client-billing-guideline-exceptions-repeat-across-matters","title":"How often do client billing guideline exceptions repeat across matters?","summary":"A measurement protocol for counting repeated client guideline exceptions across matters, with definitions, sampling rules, evidence standards, and reporting limits.","cluster":"Billing guidelines","finding":"A repeat exception rate is useful only when the same guideline rule, matter population, and evidence standard are applied to every counted item.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often the same client billing guideline exception appears across different matters in a defined billing period. The purpose is to separate a one-off correction from a rule that keeps producing the same problem. The unit is an exception event, not a time entry and not a matter, because one matter can generate several distinct exceptions. The result is a description of the observed population, not an audit opinion or a claim about the client's intent.","The scope should name the client or client group, the matters included, the billing period, and the guideline version in force. A protocol that mixes clients with different guidelines will produce a repeat rate that cannot be interpreted. Record the source document and the date it became effective before collecting any exception. The question is narrow enough to answer with records, and it should stay narrow when the queue is busy."]},{"heading":"Population and unit of analysis","paragraphs":["Define the eligible population as every prebill line or invoice reviewed under the named guideline during the window. State whether lines, invoices, or matters are the denominator and keep that choice consistent throughout the analysis. A line-level rate answers a different question from a matter-level rate, and both can be useful when labeled correctly. Never switch the denominator midway because the first result looked unhelpful.","Count an exception event when a reviewer identifies a guideline departure and records the rule, the evidence, and the disposition. If the same line is reopened and reclassified, keep the original event and record the later disposition as a linked update. A reopened item is not a new exception unless it concerns a different rule or a different line. This rule prevents the same problem from being counted twice and inflating the repeat rate."]},{"heading":"Defining a guideline exception","paragraphs":["Write the exception definition as a test that two reviewers can apply to the same record. For example, a block-billing exception exists when a narrative combines two or more distinct tasks in a way the client guideline prohibits. The definition should name the rule, the field inspected, and the evidence that confirms the departure. A definition that depends on the reviewer's general impression will not support a repeat count.","Distinguish a guideline exception from a data error and from a billing judgment. A missing matter number is a data error, while a rate that exceeds the agreed schedule may be a guideline exception with a separate approval path. A decision to reduce a charge for relationship reasons is a judgment, not a guideline departure. Keep these categories separate so the repeat rate measures the rule it claims to measure."]},{"heading":"Evidence standard","paragraphs":["Every counted exception needs the source record, the guideline reference, the observation date, and the reviewer who made the call. A screenshot taken after the prebill changed cannot prove the original state, so record the version or timestamp observed. Store the evidence under a pseudonymous case key with the crosswalk in a restricted system. The evidence standard should let a second reviewer reconstruct the decision without contacting the first.","Mark missing evidence separately from a confirmed absence. If the guideline cannot be located, the item is unresolved rather than compliant. If the record shows no exception after a complete check, that is a confirmed negative and belongs in the denominator. Collapsing these states hides the difference between clean work and unexamined work. The report should show the unresolved count beside the exception count."]},{"heading":"Sampling and collection","paragraphs":["Collect consecutive reviewed items where possible, then stratify by matter type, timekeeper, and review owner. A sample drawn only from the easiest matters will understate the repeat rate and mislead the improvement effort. If the population is too large for a full count, state the sample size and the selection rule. Include adverse cases such as a missing guideline, a conflicting instruction, and a late correction.","Record the collection window, the eligible count, the number reviewed, and every exclusion with its reason. A reader should be able to reproduce the sample from the protocol and the source list. If the guideline changed during the window, split the population at the effective date instead of blending versions. A clean collection log is more valuable than a large sample with an unclear origin."]},{"heading":"Coding repeat exceptions","paragraphs":["Create a short code list before coding begins and define each code with an example and a non-example. Codes might cover narrative structure, travel time, administrative work, rate application, and documentation. Apply one primary code per exception and allow a secondary code only when the rule genuinely overlaps. Too many codes make the pattern difficult to see, while too few hide the specific rule that needs attention.","Have a second reviewer code a small overlap sample and compare the results. Disagreement is evidence that a definition or an example is weak, not necessarily that a reviewer is careless. Resolve the disagreement by clarifying the codebook before coding the rest of the population. Record the change and its effective date so the earlier and later results can be interpreted honestly."]},{"heading":"Analysis and reporting","paragraphs":["Report the eligible count, the reviewed count, the exception count, and the repeat count by code and by matter. Show the unresolved and missing-evidence counts beside the main result rather than in a footnote. If the sample is small, report the raw counts and avoid a precise-looking percentage. A simple table with clear denominators is more useful than a polished chart that hides the population.","Separate observation from interpretation in the report. The observation is that a code appeared in a certain number of matters; the interpretation is that the guideline summary or the intake check may need repair. Give the accountable owner the decision the report supports, such as revising a template or adding a review checkpoint. Do not imply that the repeat rate measures a person's performance."]},{"heading":"Limits and sources of error","paragraphs":["Small samples are sensitive to one matter, and a repeat rate can move sharply when a single large client enters or leaves the window. Reviewer disagreement, changing guidelines, and incomplete records can also distort the result. The report should state these limits next to the finding rather than leaving them to the reader. A limitation that is not written down tends to disappear when the result is summarized.","The public sources cited in this protocol frame recordkeeping, privacy, security, and internal control practice; they do not provide a result for the firm's sample. The method cannot infer missing work from a clean summary or prove that an unrecorded exception did not occur. Use the result to improve the operating system, not to judge professional worth or to replace client-specific advice. A cautious reading is part of a credible measurement practice."]},{"heading":"Retention and privacy","paragraphs":["Keep the codebook, the sample list, and the evidence references for the period named in the firm's retention policy. Store the evidence under a pseudonymous case key and keep the crosswalk in a restricted system. Do not place client-confidential narrative in a shared notes file that is broader than the review team. A repeat study is useful only when the records behind it remain readable and appropriately protected.","When the guideline or the sample changes, archive the prior version rather than overwriting it. A later reviewer may need to know which rule applied to an earlier exception. Record the date the version was retired and the person who approved the change. Retention is part of the method because a result without its source cannot be reproduced."]},{"heading":"Applying the result to the guideline summary","paragraphs":["Use the most frequent repeat codes to decide which parts of the guideline summary need a clearer example or a new check. A code that appears across several matters is a stronger candidate for a template change than a single difficult entry. Ask the review owner to confirm the interpretation before changing the summary. The goal is a smaller repeat rate in the next window, not a longer list of rules.","Add one prebill checkpoint for the leading code and assign an owner to test it. Run the same protocol after the change and compare the counts by code and matter. If the repeat rate does not move, the checkpoint may be addressing the symptom rather than the cause. Record what was tried so the next reviewer does not repeat the same experiment."]},{"heading":"Review cadence","paragraphs":["Set a review date for the result and name the person who will read it. Re-run the protocol after a guideline change, a template change, or a shift in the client mix, because the earlier rate may no longer describe the queue. Compare the same definitions and report what moved, what did not, and what remains unknown. A report without a review owner becomes an archive rather than a control.","Choose one next action from the review: fix the guideline summary, simplify a field, add a prebill check, or stop the work until the owner decides. Assign the action and a date, then test whether the repeat rate changes in the next window. Keep the protocol, codebook, sample file, and open questions together so a later reviewer can repeat the method. The value of the exercise is the improvement it prompts, not the number alone."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/how-often-do-client-billing-guideline-exceptions-repeat-across-matters.webp"},{"slug":"what-share-of-e-billing-rejections-are-preventable-at-intake","title":"What share of e-billing rejections are preventable at intake?","summary":"A measurement protocol for classifying e-billing rejections by cause and estimating how many could have been prevented before submission.","cluster":"E-billing","finding":"A rejection is preventable at intake only when the missing check, field, or approval could have been completed before the original submission.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of e-billing rejections in a defined period could have been prevented by a check available before submission. The question is about the intake process, not about whether the client should have accepted the invoice. A rejection caused by a genuine billing dispute may be valid even when the firm disagrees with it. The protocol separates technical and completeness defects from substantive billing objections so the prevention rate is not inflated.","Name the clients, portals, invoice types, and period included in the review. Different portals enforce different rules, and a rejection rate blended across systems can hide a single integration defect. Record the portal version or rule set when it is available. The scope should also state whether resubmissions are counted as separate events or linked to their original invoice."]},{"heading":"Population and unit of analysis","paragraphs":["Define the unit as one rejection event tied to one original invoice submission. If the same invoice is rejected twice for different reasons, count two events but link them to the same invoice. If a rejection is reversed on appeal without a new submission, record the appeal as a disposition rather than a second event. This structure keeps the denominator tied to submissions and prevents double counting.","The eligible population is every invoice submitted through the named portals during the window, including invoices that were accepted on the first attempt. Without the accepted submissions, the rejection count has no denominator and the prevention rate cannot be calculated. Record the total submissions, the first-attempt acceptances, the rejections, and the resubmissions. If the portal does not expose a submission log, document the gap before estimating."]},{"heading":"Classifying rejection causes","paragraphs":["Build a cause list from the portal's actual rejection codes, then add a small set of local categories for codes that are too broad. Technical causes include invalid file formats, missing identifiers, and malformed fields. Completeness causes include missing timekeeper data, absent supporting documents, and incomplete matter records. Substantive causes include rate disputes, narrative objections, and charges the client believes are outside the guideline.","Assign one primary cause per rejection and record the evidence used to classify it. A rejection that cites a missing field should be classified from the portal message and the submitted file, not from memory. If the cause is ambiguous, mark it unresolved and keep it out of the preventable numerator. A cause list that changes with each reviewer will not support a stable comparison."]},{"heading":"Deciding whether a rejection was preventable","paragraphs":["A rejection is preventable at intake when the defect could have been detected and corrected before the original submission using information the firm already had. A missing matter identifier is preventable if the field was available in the billing system. A rate dispute is not preventable in the same sense because it requires a client decision or an interpretation. Apply the test to the cause, not to the person who submitted the invoice.","Record the check that would have caught the defect and the point in the workflow where it could have run. A check that depends on information received after submission is not an intake control. If the only prevention is a client conversation, classify the rejection as substantive rather than preventable. This distinction keeps the metric honest and directs effort toward changes the team can actually make."]},{"heading":"Evidence standard","paragraphs":["Keep the original submission file, the portal rejection notice, the timestamp, and the resubmission record for every event. The original file is necessary to confirm what the portal received and to test whether a field was actually missing. A later corrected file cannot prove the state of the first submission. Store the evidence with the invoice identifier and restrict access to the approved billing folder.","When the portal overwrites the submission, export a copy before making changes and note that the export is the best available evidence. If no copy exists, mark the evidence gap rather than assuming the cause. A rejection classification without the original file is an inference, and the report should label it as such. The evidence standard protects the analysis from becoming a collection of recollections."]},{"heading":"Sampling and collection","paragraphs":["Collect every rejection in the window when the volume is manageable, because rejections are usually less numerous than submissions. If sampling is necessary, stratify by portal, client, and cause so the preventable share is not dominated by one system. Include resubmissions and appeals in the collection log even when they are excluded from the numerator. Document every exclusion and the reason.","Record the collection window, the total submissions, the rejection count, and the number classified. A reviewer should be able to reproduce the population from the portal log and the invoice list. If a portal changes its validation rules during the window, split the data at the change date. A rule change can make an earlier defect impossible to reproduce and should be visible in the report."]},{"heading":"Analysis and reporting","paragraphs":["Report the preventable share as a count and a proportion of classified rejections, with the unclassified count shown separately. Break the result down by cause, portal, and client so the owner can see where the intake check would have the most effect. Avoid a single blended percentage that hides a concentrated defect. A table with raw counts and a short note on the denominator is usually sufficient.","State the action implied by each leading cause. A missing field may call for a matter-opening validation, while a missing document may call for a submission checklist. A substantive dispute belongs in the client communication workflow, not the intake check. Give the accountable owner a decision to make rather than a general recommendation to improve quality."]},{"heading":"Limits and sources of error","paragraphs":["The preventable share depends on the cause definitions and the quality of the portal evidence. A rejection classified as substantive may later prove to be a technical defect, and a technical defect may hide a client objection. Small volumes produce unstable proportions, especially when one client dominates the submissions. The report should state these limits and avoid treating the share as a fixed property of the team.","The cited public sources frame data security, privacy, recordkeeping, and internal control practice; they do not provide a rejection rate for the firm. The protocol cannot prove that an unrecorded defect did not occur or that a client would have accepted a corrected invoice. Use the result to choose an intake control and test it in the next window. The number is a starting point for improvement, not a performance verdict."]},{"heading":"Coordinating with portal support","paragraphs":["When a rejection code is unclear, ask the portal support contact for the validation rule and the accepted field format. Record the ticket reference and the rule version with the rejection. A verbal answer from support is useful, but it should be written into the matter note before the next submission. The support response often explains whether the defect was technical, completeness-related, or substantive.","Do not treat a support explanation as a client approval. The portal can explain its validation logic without deciding whether a charge should be billed. Keep the two conversations separate and record who owns each. A support ticket that closes a technical question may still leave an open billing decision. The billing owner should confirm the substantive position before the next submission."]},{"heading":"Testing an intake control","paragraphs":["Choose one prevention check and apply it to the next set of submissions for a single portal or client. Record the submissions, the rejections, and the cause codes before and after the change. A check that reduces the leading cause without adding a new delay is a candidate for wider use. A check that only moves the work to a different queue is not an improvement.","Review the test with the billing manager and the system owner before expanding it. Ask whether the check catches the defect at the right point and whether the evidence is available at that point. If the check depends on a field that arrives late, it cannot prevent the rejection. Document the decision and the date so the next test starts from a known baseline."]},{"heading":"Review cadence","paragraphs":["Re-run the protocol after a portal change, a template change, or a new client guideline. Compare the same causes and the same denominator so the movement is interpretable. Set a review date and name the billing manager or system owner who will read the result. A report that no one owns will not change the intake process.","Choose one prevention action, implement it, and measure whether the leading cause declines. Keep the cause list, evidence samples, and open questions together for the next review. If the preventable share does not move, the action may have addressed a symptom rather than the intake check. The review should end with a specific test, not a general commitment to be more careful."]}],"sources":[{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"Cybersecurity and Infrastructure Security Agency best practices","url":"https://www.cisa.gov/topics/cybersecurity-best-practices"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Department of Health and Human Services HIPAA","url":"https://www.hhs.gov/hipaa/index.html"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/what-share-of-e-billing-rejections-are-preventable-at-intake.webp"},{"slug":"how-much-prebill-review-time-goes-to-locating-source-records","title":"How much prebill review time goes to locating source records?","summary":"A time-allocation protocol for measuring how much prebill review effort goes to finding source records instead of reviewing the billing substance.","cluster":"Prebill workflow","finding":"Locating source records is a measurable and often invisible part of prebill review that should be separated from substantive review before improvement work begins.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much of the prebill review effort is spent locating source records rather than evaluating the billing substance. Locating includes searching for the matter record, the client guideline, the time entry, the approval, or the supporting document. Substantive review includes reading the evidence and deciding whether the entry is complete and appropriate. The distinction matters because search time is often hidden inside a general review estimate.","Define the matters, reviewers, period, and review stage included in the measurement. A prebill review can involve an assistant, a billing manager, and a partner, and each role may spend time differently. Record the role and the stage for every observation. The question is descriptive, and it should not be used to compare individual reviewers without accounting for the records they were given."]},{"heading":"Unit of analysis and observation","paragraphs":["Use one review episode as the unit, from the moment the reviewer opens the prebill to the moment the review is recorded as complete. If the review is interrupted and resumed, keep the elapsed work time separate from the wall-clock time. A short interruption should not make a routine review look inefficient. The observation should capture the start state, the end state, and the reason for any pause.","Record the matter, the reviewer role, the number of lines, and the systems used. These variables help explain why one review took longer than another. A large matter with a new client may legitimately need more search time than a repeat matter with a stable record. The protocol should describe the work, not rank the people doing it."]},{"heading":"Defining search time","paragraphs":["Search time begins when the reviewer starts looking for a record and ends when the record is found or the reviewer decides it is unavailable. It includes opening systems, checking messages, asking a colleague, and comparing versions. It does not include reading the record once found or writing the review note. The boundary should be written down and applied consistently so two observers classify the same activity the same way.","Some activities blend search and review, such as reading a guideline to find the applicable rule. Classify the activity by its primary purpose and record the ambiguity rather than forcing a false precision. If a reviewer spends time deciding whether a document is the right version, that is search until the version is confirmed. A short decision rule at the top of the observation form reduces disagreement."]},{"heading":"Evidence and data collection","paragraphs":["Collect the observation with a simple form that records the start time, each search segment, the source sought, and the outcome. Ask reviewers to note the system and the reason for the search in a few words. Do not require a stopwatch for every task if the interruption would distort the work; a short retrospective estimate can supplement direct observation. Record which method was used for each episode.","Keep the observation data separate from the review record so the measurement does not change the work being measured. If the team is uncomfortable with direct timing, start with a sample of self-reported episodes and state the method limitation. A consistent method matters more than a sophisticated one. The goal is a useful estimate of where effort goes, not a billing audit of the reviewer."]},{"heading":"Sampling and stratification","paragraphs":["Collect episodes across matter types, client guidelines, reviewer roles, and record ages. Search time is likely to be higher for new matters, incomplete records, and clients with long guidelines. A sample drawn only from repeat matters will understate the problem. If the population is large, stratify and report the counts for each stratum rather than a single average.","Include episodes where the source was never found, because an unavailable record can consume more time than a successful search. Record the reason it was unavailable and the escalation that followed. Excluding these episodes would make the search problem look smaller than it is. The report should show both the successful and unsuccessful searches. An unavailable record that was never created is a different finding from one that exists but cannot be located."]},{"heading":"Analysis and reporting","paragraphs":["Report the median and range of search time per episode, the share of total review time, and the sources that took the longest to locate. A median is more robust than an average when one difficult matter dominates the sample. Show the number of episodes and the method used to collect them. Avoid presenting a precise percentage when the sample is small or the method is retrospective.","Group the findings by source type so the owner can see whether the problem is the matter record, the guideline, the time entry, or the approval trail. For each group, describe the current location and the access barrier. A finding that says reviewers spend time searching is less useful than one that says the prior approval is stored in a personal inbox. The report should point to a specific fix."]},{"heading":"Limits and sources of error","paragraphs":["Direct observation can change behavior, and self-report can undercount short searches. Reviewers may disagree about where search ends and review begins, especially when a document is hard to interpret. The record itself may be incomplete, and a missing document can be recorded as a search failure even when it was never created. State these limits with the result.","The cited public sources frame recordkeeping, privacy, and internal control practice; they do not provide a time estimate for the firm. The protocol measures the observed episodes, not the value of the review or the quality of the decision. Do not use the result to judge individual performance without adjusting for the records and systems each reviewer received. The purpose is to improve access to evidence."]},{"heading":"What counts as substantive review","paragraphs":["Substantive review begins when the reviewer has the record in front of them and starts evaluating the entry against the standard. Reading a guideline to confirm the applicable rule can be part of that evaluation, but searching for the guideline is not. Write examples for the team so the boundary is not left to individual interpretation. The distinction should be stable enough to compare episodes across reviewers.","A fast review is not automatically a good review, and a slow review is not automatically a thorough one. The time measure should be paired with a small quality sample so speed does not become the only goal. If search time falls while defect rates rise, the access change may have hidden the evidence rather than improved it. Report both dimensions when the owner is deciding whether to keep a change. The quality sample should use the same checklist before and after the pilot."]},{"heading":"Testing an access improvement","paragraphs":["Pilot one access change with a single client or matter type, such as a linked source panel or a standard evidence folder. Measure search time and review quality before and after the change on comparable episodes. Ask reviewers whether the new location actually reduced the number of places they had to check. A change that adds another system without removing a search step may not help.","Keep the pilot small enough to reverse if the evidence quality drops. Compare a sample of reviewed entries against the same checklist used before the change. If the new access path makes the right document easier to find, both search time and consistency should improve. Record the result and the date before expanding the change."]},{"heading":"Review cadence","paragraphs":["Repeat the measurement after a record-location change, a system migration, or a new guideline template. Compare the same roles and source types so the movement is meaningful. Set a review date and name the operations owner who will act on the result. A measurement that is not repeated will not show whether the fix worked.","Choose one access improvement and test it on the next sample. The improvement might be a linked source panel, a standard folder structure, or a matter-opening field that stores the guideline reference. Keep the observation forms and the analysis notes together so a later reviewer can repeat the method. The measure earns its place when it reduces search time without reducing review quality."]}],"sources":[{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"U.S. Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"},{"label":"U.S. Small Business Administration compliance guidance","url":"https://www.sba.gov/business-guide/manage-your-business/stay-legally-compliant"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/how-much-prebill-review-time-goes-to-locating-source-records.webp"},{"slug":"do-two-reviewers-agree-on-the-same-time-entry-defects","title":"Do two reviewers agree on the same time-entry defects?","summary":"A reliability protocol for testing whether two reviewers classify the same time-entry defects consistently before a defect rate is trusted.","cluster":"Evidence quality","finding":"Reviewer agreement is a precondition for a meaningful time-entry defect rate, and disagreement should be studied before the rate is reported.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often two qualified reviewers reach the same classification when they examine the same time entries. The question is about reliability, not about which reviewer is correct. A defect rate built on inconsistent classifications describes the reviewers as much as the records. The protocol should be run before a defect rate is used to compare teams, periods, or training approaches.","Name the review standard, the entry population, the reviewers, and the period. The reviewers should be qualified to apply the standard and should not be the people who created the entries. If one reviewer is a trainer and the other is new, the disagreement may reflect training rather than the standard. Record the roles and experience so the result can be interpreted."]},{"heading":"Unit of analysis","paragraphs":["Use one time entry as the unit and classify it against the same checklist independently. If an entry contains several defects, record the primary defect and any secondary defects using the codebook. Do not let reviewers discuss the entry before both have recorded a classification. The independence of the first pass is what makes the agreement result meaningful.","Keep the entry identifier, the reviewer, the classification, and the evidence note for each observation. If a reviewer changes a classification after discussion, preserve the original and record the change separately. The original classification is the data; the discussion is a learning event. Mixing the two makes the agreement rate look better than it is."]},{"heading":"Defining the defect categories","paragraphs":["Write a codebook with a definition, a positive example, and a negative example for each defect category. Categories might include insufficient narrative, incorrect matter, unsupported time, duplicate entry, and rate mismatch. A category without an example invites each reviewer to use a personal threshold. The codebook should also state what is not a defect so reviewers do not inflate the count.","Test the codebook on a small set of entries before the main review and revise any category that produces confusion. Record the revision and the date so later results can be compared. If a category cannot be made reliable, consider merging it with a broader category or removing it. A smaller reliable codebook is more useful than a detailed one that no two reviewers apply the same way."]},{"heading":"Independent review procedure","paragraphs":["Give both reviewers the same records, the same standard, and the same time limit. Remove identifying information that could influence the classification, such as the timekeeper's name or the reviewer's prior notes. Ask each reviewer to record a confidence level and a short evidence note for every entry. The confidence field helps distinguish a true disagreement from a guess.","Do not allow one reviewer to see the other's classification until both have submitted. Use separate forms or a system that hides the first response. If the review is conducted in person, collect the forms before any discussion begins. The procedure should be simple enough to repeat without a research team. A shared screen or a visible spreadsheet defeats the independence the study depends on."]},{"heading":"Measuring agreement","paragraphs":["Report the raw agreement rate and the agreement expected by chance, then calculate a chance-corrected statistic such as Cohen's kappa. Raw agreement alone can look high when one category dominates the sample. Report the counts behind the statistic and the confidence interval when the sample is large enough. If the sample is small, present the counts and avoid overstating precision.","Break the result down by defect category, because a strong overall statistic can hide a weak category. A category with low agreement may need a clearer definition or more training. Also report the entries with no defect, since agreement on clean records is part of the reliability picture. The report should show where the reviewers actually differed."]},{"heading":"Resolving disagreements","paragraphs":["Discuss a sample of disagreements after the independent pass and record the reasoning, not only the final answer. The discussion should identify whether the codebook, the evidence, or the reviewer's interpretation caused the difference. Update the codebook when the same ambiguity appears more than once. Do not simply tell one reviewer to match the other.","If the reviewers cannot resolve a disagreement, escalate it to the owner of the review standard. That person decides the interpretation and documents the rule for future entries. A decision that lives only in a meeting will not reach the next reviewer. The resolution should become part of the codebook and the training material. Record the date of the ruling so later entries can be compared against the same standard."]},{"heading":"Analysis and reporting","paragraphs":["Report the number of entries, the number of reviewers, the agreement statistic, and the category-level results. State the review standard and the codebook version used, because a different standard may produce a different result. Keep the observation forms and the disagreement log with the report. A reader should be able to see how the classifications were made.","Separate the reliability finding from any claim about the true defect rate. High agreement means the reviewers applied the standard consistently, not that the standard captures every problem. Low agreement means the defect rate should be treated as provisional until the standard improves. Give the owner a decision about the codebook or the training rather than a verdict about the team."]},{"heading":"Limits and sources of error","paragraphs":["Two reviewers can agree on a wrong interpretation, and a small sample can produce a misleading statistic. The order of entries, fatigue, and prior familiarity with the matters can also influence classifications. Reviewers who helped design the codebook may apply it differently from reviewers who did not. The report should state these limits and avoid generalizing beyond the observed sample.","The cited public sources frame recordkeeping, privacy, and internal control practice; they do not provide an agreement result for the firm. The protocol measures consistency under the conditions of the test, not the professional worth of any reviewer. Use the result to improve the standard and the training, not to rank people. A reliability check is a tool for better measurement."]},{"heading":"Calibration after the study","paragraphs":["Use the disagreement examples in a short calibration session with the reviewers who will apply the standard. Ask each person to explain the evidence that drove their classification, not only the label they chose. Update the codebook where the same ambiguity appears more than once. A calibration session is more useful than a general reminder to be consistent.","Record who attended, the codebook version used, and the examples discussed. Re-test a small set of entries after the session to see whether agreement improved. If it did not, the problem may be the evidence rather than the training. Keep the session notes with the study so a later reviewer can see how the standard evolved."]},{"heading":"When to trust a defect rate","paragraphs":["Set a reliability threshold with the owner of the review standard before using the defect rate for a management decision. A rate built on low agreement should be reported as provisional, with the disagreement examples visible. Do not hide the reliability result in an appendix when the main number depends on it. The reader needs to know how much confidence the classification supports.","Even a reliable rate describes the sample and the standard, not every entry in the population. Report the sample size, the period, and the codebook version beside the result. If the rate is used to compare teams, confirm that both teams used the same standard and the same evidence access. A comparison across different standards is not a comparison of performance."]},{"heading":"Review cadence","paragraphs":["Repeat the agreement check after a codebook change, a new review system, or a significant change in the reviewer group. Compare the same categories and report what improved and what did not. Set a review date and name the owner of the standard. A one-time agreement study becomes stale when the work changes. Schedule the repeat before the next major queue change rather than waiting for a dispute.","Choose one improvement based on the weakest category and test it in the next round. The improvement might be a new example, a shorter checklist, or a calibration session. Keep the codebook versions and the observation forms together so the change can be evaluated. The goal is a review standard that two qualified people can apply with reasonable consistency."]}],"sources":[{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"NIST Cybersecurity Framework","url":"https://www.nist.gov/cyberframework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/do-two-reviewers-agree-on-the-same-time-entry-defects.webp"},{"slug":"how-long-does-an-invoice-follow-up-promise-stay-open","title":"How long does an invoice follow-up promise stay open?","summary":"A measurement protocol for tracking how long client invoice promises remain open and where the follow-up clock actually stops.","cluster":"Collections","finding":"The age of an invoice is not the same as the age of its latest promise, and a useful follow-up measure keeps both clocks visible.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how long a client's invoice follow-up promise stays open before it is resolved, renewed, or escalated. The promise may be a commitment to pay, to review a charge, or to route the invoice to another approver. The measure is not the invoice age, because an old invoice can have a recent commitment. The question is about the promise cycle and the action that follows it.","Name the client group, the invoice population, the period, and the channels included in the review. A promise made in a phone call and a promise made in a portal comment may be recorded differently. State whether the measurement includes all open promises or only those past a threshold. The scope should also define what counts as a resolution for the purpose of the study."]},{"heading":"Unit of analysis","paragraphs":["Use one promise event as the unit, from the date the client makes the commitment to the date it is resolved, renewed, or escalated. If the client makes several promises on the same invoice, keep each event separate and link them to the invoice. A renewed promise starts a new cycle but should not erase the earlier cycle from the record. This structure shows whether the relationship is moving or repeating.","Record the invoice, the client contact, the channel, the promised action, and the promised date. If the promise has no date, record that absence explicitly rather than inventing one. An undated promise is a finding in itself because it cannot be aged or escalated. The unit should be observable from the log without asking the original owner to reconstruct it."]},{"heading":"Defining a promise and a resolution","paragraphs":["A promise is a statement by an authorized client contact about a future action on the invoice. A request for information is not a promise, and neither is a courtesy acknowledgment with no commitment. A resolution is the event that closes the promise, such as payment received, a credit approved, a dispute routed to a formal process, or a new promise with a defined date. Write these definitions into the protocol before counting.","Distinguish a resolved promise from a closed invoice. The invoice may remain open because of a partial payment or a separate dispute, even when the promise was fulfilled. Conversely, an invoice can be closed administratively while the underlying question remains unresolved. The measure should follow the promise, not the invoice status alone. This prevents a clean invoice report from hiding an open commitment."]},{"heading":"Evidence standard","paragraphs":["Every promise should have a dated record of what the client said and who said it. A summary written weeks later is weaker evidence than a contemporaneous note. If the promise was made by phone, record the call date and the person reached. If it was made in a portal, keep the message reference. The evidence should let a reviewer confirm the commitment without contacting the client again.","Record missing or unclear evidence as its own state. A note that says the client will pay soon is not a dated promise and should not be treated as one. If the contact is not authorized to make the commitment, mark the promise as unverified and route it to the relationship owner. Collapsing these states would make the follow-up process look more controlled than it is."]},{"heading":"Sampling and collection","paragraphs":["Collect promises from consecutive invoices and include both resolved and unresolved events. A sample of only closed promises will understate the time open and hide the items that never resolved. If the population is large, stratify by client, aging bucket, and channel. Include promises with no date and promises with multiple renewals so the tail of the distribution is visible.","Record the collection window and the criteria used to identify a promise in the log. If the team changed its logging practice during the window, split the data at the change date. A new field or a new reminder process can change both the number of promises recorded and their apparent age. The report should make that change visible rather than blending the periods."]},{"heading":"Measuring time open","paragraphs":["Calculate the time from the promise date to the resolution date for closed events and from the promise date to the observation date for open events. Report the median, the range, and the number of events that exceeded the promised date. A median that ignores open events can make the process look faster than it is. Show the open count beside the closed count so the reader sees both.","Separate a missed promise date from a renewed promise. A renewed promise may be a legitimate extension or a sign that the original commitment was not serious. Record the reason for the renewal when it is known. The distinction helps the owner decide whether the issue is client communication, internal follow-up, or the original due date."]},{"heading":"Analysis and reporting","paragraphs":["Report the promise count, the resolved count, the open count, the median days open, and the share past the promised date. Break the result down by channel and client group where the numbers allow. Avoid a single average that mixes a one-week promise with a one-quarter promise. A small table with counts and medians is more useful than a precise-looking ratio.","State the action implied by the result. A cluster of promises past their date may call for a reminder rule or a different contact route. A cluster of undated promises may call for a logging standard. A cluster of renewals may call for a conversation about the client's approval process. Give the owner a specific decision rather than a general warning about aging."]},{"heading":"Limits and sources of error","paragraphs":["The log may omit promises made outside the recorded channels, and the client contact may not be authorized to commit. A promise can also be recorded differently by different team members, especially when the client is vague. Small samples produce unstable medians, and a single large account can dominate the result. The report should state these limits.","The cited public sources frame recordkeeping, privacy, and internal control practice; they do not provide a promise age for the firm. The protocol measures the observed log, not the client's intent or the firm's collection performance. Use the result to improve the follow-up process and the record, not to judge a client relationship. A cautious reading protects both the analysis and the relationship."]},{"heading":"Coordinating with the billing team","paragraphs":["Share the promise aging summary with the billing manager and the relationship owner at the same weekly review. A promise that is old may need a relationship conversation rather than another reminder. A promise that is repeatedly renewed may need a different contact or a formal dispute path. The follow-up owner should not have to decide those questions alone.","Separate delays caused by the client from delays caused by the firm. A client waiting for a corrected invoice is not the same as a client ignoring a valid one. Record the responsible party in the log so the aging report does not blame the wrong side. This distinction also helps the team choose the right next action."]},{"heading":"Testing a reminder rule","paragraphs":["Pilot a reminder at the promised date for one client group and compare the missed-date share with a similar group. Keep the reminder professional and specific to the commitment the client made. If the reminder produces more renewals without more resolutions, the issue may be the client's approval process rather than the firm's follow-up. Adjust the rule based on the result.","Review the pilot with the billing manager before expanding it. Ask whether the reminder improved communication or damaged the relationship. A rule that works for one client may be inappropriate for another, especially where the balance is sensitive. Document the test, the result, and the decision to continue or stop. Keep the client's preferred channel in the rule so the reminder does not create a new complaint."]},{"heading":"Review cadence","paragraphs":["Review the result monthly while the follow-up process is being changed, then quarterly once the measure is stable. Re-run the protocol after a logging change or a new client portal, because the recorded promise population may shift. Set a review date and name the billing manager who will act on it. A measure that is not reviewed will not change the queue.","Choose one improvement, such as requiring a date for every promise or adding a reminder at the promised date. Test whether the open count and the missed-date share move in the next period. Keep the definitions, the sample, and the open questions together so the next reviewer can repeat the method. The goal is a follow-up process that keeps its commitments visible."]}],"sources":[{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"U.S. Small Business Administration compliance guidance","url":"https://www.sba.gov/business-guide/manage-your-business/stay-legally-compliant"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/how-long-does-an-invoice-follow-up-promise-stay-open.webp"},{"slug":"where-do-matter-record-updates-stall-before-billing-close","title":"Where do matter record updates stall before billing close?","summary":"A stall-point protocol for finding where matter record updates wait before a billing close and which handoffs need a clearer owner.","cluster":"Matter records","finding":"Matter record updates usually stall at a handoff rather than at a single step, so the measurement should locate the waiting state and the missing owner.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks where matter record updates wait before a billing close and how long they remain in each waiting state. A stall can occur when a request is sent to a matter team, when a partner approval is pending, or when a system field cannot be edited by the person who found the gap. The question is about the handoff, not about the speed of any individual. The result should show which waiting states consume the most calendar time.","Define the matter population, the billing period, and the record fields included in the review. A close may involve client entity changes, rate updates, timekeeper assignments, billing contacts, and matter status changes. Include only fields that affect the close or the invoice, and state that boundary. A broad data-quality review would produce a different and less actionable result."]},{"heading":"Unit of analysis","paragraphs":["Use one update request as the unit, from the date the gap is identified to the date the field is corrected or formally deferred. If a request contains several fields, record each field separately when they have different owners or waiting states. A combined request can hide the one field that delayed the close. Link the fields to the same request identifier so the relationship is preserved.","Record the source of the request, the current value, the requested value, and the evidence for the change. A vague request such as fix the matter record cannot be aged or routed. The unit should show what was needed, who was asked, and what happened next. This structure supports both the measurement and the correction workflow."]},{"heading":"Defining the waiting states","paragraphs":["List the possible states in the handoff: identified, assigned, awaiting evidence, awaiting approval, ready to update, updated, and deferred. Define each state with an observable event and a timestamp. A request is awaiting evidence when the owner has asked for a document, not when the requester is still gathering it. Clear state definitions make the stall visible without relying on a narrative.","Separate a wait caused by missing information from a wait caused by missing authority. The first may be resolved by a document, while the second needs a person who can approve the change. A request that sits in the wrong state will be routed to the wrong remedy. The state list should be short enough to apply consistently and specific enough to guide action."]},{"heading":"Evidence standard","paragraphs":["Every state change should have a date, a person or system, and a short note that explains the transition. An email request with no response is evidence of a wait, but it is not evidence that the owner accepted the request. Record the channel and the recipient when the request is sent. If the owner responds in a meeting, add the note the same day.","Keep the source for the corrected value, such as the engagement letter, the client message, or the approved rate notice. A field changed without a source may be correct, but the next reviewer cannot tell. Mark a deferred request with the reason and the person who accepted the deferral. An unexplained deferral is a stall that has simply been renamed."]},{"heading":"Sampling and collection","paragraphs":["Collect update requests from several billing cycles so the sample includes ordinary and peak periods. A single close may be dominated by a holiday, a system outage, or one large client. If the volume is large, stratify by field, matter type, and requesting role. Include requests that were never resolved, because those are often the longest stalls.","Record the collection window and the source systems used to reconstruct each request. If a request moved through a channel that is not retained, note the evidence gap. Do not infer a state from the absence of a message unless the channel is known to be complete. A clear collection note helps a later reviewer judge the result."]},{"heading":"Measuring stall time","paragraphs":["Calculate the calendar time in each state and the total time from identification to correction or deferral. Report the median and the longest cases, with the number of requests in each state. Calendar time is the right measure for a close because the invoice waits on the calendar, not on the effort spent. A request that required ten minutes of work but waited five days is still a five-day stall.","Separate business days from weekends and holidays if the billing calendar treats them differently. State the rule and apply it consistently. A long wait that spans a holiday may look different from a long wait in an ordinary week. The report should show enough detail for the owner to judge whether the delay was structural or seasonal."]},{"heading":"Analysis and reporting","paragraphs":["Report the request count, the resolved count, the deferred count, and the median time in each waiting state. Identify the state that contributes most to the total delay and the field that appears most often. A chart of average time by state can help, but the raw counts should remain visible. The owner needs to know where to intervene, not only that the process is slow.","State the action implied by the leading stall. A wait for approval may call for a named backup, while a wait for evidence may call for a matter-opening checklist. A system permission problem may need an access change rather than a new policy. Give the owner one decision and one test for the next close. A report with many recommendations is less likely to produce a change."]},{"heading":"Limits and sources of error","paragraphs":["The record of a request may be incomplete, especially when people coordinate in meetings or hallway conversations. A request that was never logged cannot be measured, and a request logged late may appear faster than it was. Different fields may have different owners and different evidence standards. The report should state these limits and avoid treating the measured states as the whole process.","The cited public sources frame recordkeeping, privacy, and internal control practice; they do not provide a stall time for the firm. The protocol measures the observed requests, not the quality of the underlying matter record. Use the result to improve the handoff and the evidence standard, not to assign blame. A stalled request is usually a system problem before it is a person problem."]},{"heading":"System permissions and access","paragraphs":["Map who can edit each field and which role can approve a change. A request that waits because the requester lacks permission is a different problem from a request that waits for a decision. Record the permission gap and route it to the system owner rather than asking the matter team to work around it. Shared logins may solve the immediate task while destroying the audit trail.","When a permission change is needed, state the field, the role, and the reason in the request. Ask for an audit trail that records the user and the date of each change. A permission fix that cannot be audited may create a new control problem. Review access after the close to confirm the change did not widen beyond the intended role."]},{"heading":"Testing a handoff fix","paragraphs":["Pilot one handoff change on a single billing close, such as a named backup approver or a required field at matter opening. Compare the stall time and the evidence quality against the prior close. A faster handoff that produces an unsupported field is not an improvement. Ask the reviewer who receives the record whether the change made the correction easier to verify.","Keep the pilot limited until the result is clear. If the fix works, document the new step and update the matter-opening checklist. If it does not, record why before trying another change. The measurement should end with a decision about the handoff, not only a description of the delay. A second close gives a better signal than a single busy week."]},{"heading":"Review cadence","paragraphs":["Repeat the measurement after a close, an access change, or a new matter-opening process. Compare the same states and fields so the movement is interpretable. Set a review date and name the operations owner who will act. A one-time review can identify a stall, but only a repeat can show whether the fix held. Keep the prior state definitions so a change in the measure is not mistaken for a change in the process.","Choose one handoff improvement and test it in the next cycle. The improvement might be a named backup approver, a required field at matter opening, or a shared evidence folder. Keep the state definitions and the sample notes together so the next reviewer can repeat the method. The measure is useful when it shortens the wait without weakening the record."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"U.S. Small Business Administration compliance guidance","url":"https://www.sba.gov/business-guide/manage-your-business/stay-legally-compliant"},{"label":"U.S. Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/where-do-matter-record-updates-stall-before-billing-close.webp"},{"slug":"how-complete-is-the-evidence-trail-for-write-down-approvals","title":"How complete is the evidence trail for write-down approvals?","summary":"An evidence-completeness protocol for write-down approvals that tests whether each adjustment can be reconstructed by an independent reviewer.","cluster":"Controls","finding":"A write-down approval is only as strong as the evidence that lets an independent reviewer reconstruct who approved what, when, and on which basis.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how completely a write-down approval can be reconstructed from the records the firm retains. The test is whether an independent reviewer can identify the adjustment, the reason, the approver, the date, and the evidence without asking the original preparer. A complete trail does not prove that the decision was wise, but an incomplete trail makes the decision impossible to review. The question is about evidence, not about the merits of any particular write-down.","Define the write-down population, the billing period, and the approval levels included in the review. Include adjustments that were proposed but not approved, because a missing denial record can hide an unresolved request. State whether the review covers individual invoice lines, whole invoices, or both. The scope should also name the systems searched for evidence."]},{"heading":"Unit of analysis","paragraphs":["Use one write-down decision as the unit, from the request to the final disposition. If one request covers several invoices, record each invoice as a linked item under the same decision. If the approver changes the requested amount, record the proposal and the final amount separately. This structure preserves the decision history instead of reducing it to a single number.","Record the matter, the client, the amount, the reason code, the preparer, and the approver. Link the decision to the prebill or invoice record that contains the adjustment. A decision that cannot be linked to a billing record cannot be tested against the actual charge. The unit should be specific enough to support both the review and a later audit."]},{"heading":"Defining completeness","paragraphs":["A complete evidence trail has five elements: the proposed adjustment, the reason, the supporting source, the approver, and the date. It should also show the final amount if it differs from the proposal, and any condition attached to the approval. Missing any of the first five makes the decision incomplete for review. Additional elements can be useful, but they should not substitute for the core five.","Distinguish a complete trail from a persuasive narrative. A well-written explanation without the client guideline or the time entry is still incomplete. A short note with the right evidence can be complete. The protocol should score the elements rather than judge the prose. This keeps the result consistent across reviewers with different writing styles. A confident explanation is not a substitute for a dated source."]},{"heading":"Evidence standard","paragraphs":["The supporting source should be the document that establishes the basis for the adjustment, such as the client guideline, the engagement letter, a written client approval, or the time entry that contains the error. Record the source location and the date observed. If the source is a conversation, record who said what and when, and mark it as a conversation rather than a document. The reviewer should be able to find the same source again.","Keep the evidence in an approved system with access controls that match the sensitivity of the matter. Do not store client-confidential material in a personal inbox or an unmanaged desktop folder. If the evidence includes privileged content, limit the review to the people who need it. A complete trail that is not secure is not a control."]},{"heading":"Sampling and collection","paragraphs":["Collect decisions from several billing cycles and include both approved and denied requests. A sample of only approved write-downs will miss the requests that stalled or were resolved informally. If the population is large, stratify by amount, reason code, and approver. Include at least one decision that changed amount after review, because those are often the most revealing.","Record the collection window, the systems searched, and the number of decisions for which no record was found. A missing record is a finding, not an exclusion. If a decision was handled entirely in conversation, note the evidence gap and the person who can confirm it. The report should distinguish a missing file from a decision that was never made."]},{"heading":"Scoring the trail","paragraphs":["Score each decision on the five core elements and report the number of complete, partial, and missing trails. A partial trail has at least one core element but lacks another, while a missing trail has no identifiable approval record. Show the element-level counts so the owner can see whether the problem is the reason, the source, or the approver. A single completeness percentage hides which element needs repair.","Have a second reviewer score a small overlap sample and compare the results. Disagreement may mean the element definitions are unclear or the evidence is ambiguous. Resolve the definition before scoring the rest of the population. Record the codebook version so a later comparison uses the same standard. If the overlap sample is small, report the raw disagreements instead of a precise agreement rate."]},{"heading":"Analysis and reporting","paragraphs":["Report the decision count, the complete count, the partial count, the missing count, and the element-level gaps. Break the result down by reason code and approver role where the numbers allow. Avoid naming individual preparers in a report that is shared beyond the control owner. The purpose is to improve the trail, not to create a performance ranking.","State the action implied by the leading gap. A missing source may call for a required attachment in the request form. A missing approver may call for a named approval step in the workflow. A missing date may call for an automatic timestamp. Give the owner a specific change and a date to test it in the next cycle."]},{"heading":"Limits and sources of error","paragraphs":["The review can only see the records that were retained, and a missing record may reflect a retention practice rather than a missing decision. The five core elements are a minimum standard, not a full account of the client relationship. Reviewers may disagree about whether a conversation counts as sufficient evidence. Small samples produce unstable completeness rates, especially when one approver dominates the population.","The cited public sources frame recordkeeping, privacy, and internal control practice; they do not provide a completeness result for the firm. The protocol measures the evidence trail, not the fairness or propriety of the adjustment. Use the result to strengthen documentation and routing, not to second-guess a decision without its context. A complete trail is a condition for review, not a substitute for judgment."]},{"heading":"Sampling the decision context","paragraphs":["Read a small number of complete decisions in full before scoring the larger sample. The context shows whether the recorded reason matches the actual issue and whether the approver had the information needed. A trail can be complete on paper while the evidence supports a different decision. Use the reading to refine the element definitions, not to replace the scoring.","Separate a documentation gap from a disagreement about the decision. A missing source is a documentation gap, while a source that supports a different conclusion is a judgment question for the approver. Keep the two findings separate so the report does not imply misconduct where the record is merely incomplete. The owner can then choose the right remedy."]},{"heading":"Testing a documentation fix","paragraphs":["Add one required element to the request form, such as the source location or the approver role, and pilot it on the next cycle. Compare the completeness score and the review time before and after the change. A form that adds fields without improving the trail may simply move the gap. Ask the approver whether the new field made the decision easier to review.","Keep the old form and the new form available during the pilot so the comparison is fair. Document the change date and the person who approved it. If the fix works, update the scoring guide and the training material. If it does not, remove the field rather than preserving a control that produces no evidence."]},{"heading":"Review cadence","paragraphs":["Repeat the review after a change to the request form, the approval workflow, or the retention system. Compare the same elements and reason codes so the movement is meaningful. Set a review date and name the billing manager or finance owner who will act. A one-time completeness check can identify a gap, but a repeat shows whether the fix lasted.","Choose one improvement and test it in the next sample. The improvement might be a required source field, a named approver, or a same-day timestamp. Keep the scoring guide, the sample list, and the open questions together for the next reviewer. The goal is a trail that lets an independent person reconstruct the decision without relying on memory."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"NIST Privacy Framework","url":"https://www.nist.gov/privacy-framework"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"}],"publishedAt":"2026-11-06","thumbnail":"/thumbnails/november-06/how-complete-is-the-evidence-trail-for-write-down-approvals.webp"}];
